import React, { useCallback, useEffect, useRef, useState } from 'react';

export interface PomodoroProps {
  initialMinutes?: number;
  title?: string;
}

type Status = 'idle' | 'running' | 'paused' | 'finished';

function formatTime(totalSeconds: number): string {
  const safe = Math.max(0, Math.floor(totalSeconds));
  const mm = Math.floor(safe / 60);
  const ss = safe % 60;
  return `${String(mm).padStart(2, '0')}:${String(ss).padStart(2, '0')}`;
}

export default function Pomodoro({ initialMinutes = 25, title = '番茄钟' }: PomodoroProps) {
  const totalSeconds = Math.max(1, Math.floor(initialMinutes * 60));

  const [remaining, setRemaining] = useState<number>(totalSeconds);
  const [status, setStatus] = useState<Status>('idle');

  const endAtRef = useRef<number | null>(null);
  const intervalRef = useRef<number | null>(null);

  const clearTimer = useCallback(() => {
    if (intervalRef.current !== null) {
      window.clearInterval(intervalRef.current);
      intervalRef.current = null;
    }
  }, []);

  useEffect(() => {
    return () => {
      clearTimer();
    };
  }, [clearTimer]);

  const startTicking = useCallback(() => {
    clearTimer();
    intervalRef.current = window.setInterval(() => {
      const endAt = endAtRef.current;
      if (endAt === null) return;
      const left = Math.ceil((endAt - Date.now()) / 1000);
      if (left <= 0) {
        endAtRef.current = null;
        clearTimer();
        setRemaining(0);
        setStatus('finished');
      } else {
        setRemaining(left);
      }
    }, 200);
  }, [clearTimer]);

  const handleStart = useCallback(() => {
    if (status === 'running') return;
    if (status === 'finished') return;
    const base = remaining > 0 ? remaining : totalSeconds;
    endAtRef.current = Date.now() + base * 1000;
    setStatus('running');
    startTicking();
  }, [status, remaining, totalSeconds, startTicking]);

  const handlePause = useCallback(() => {
    if (status !== 'running') return;
    const endAt = endAtRef.current;
    clearTimer();
    endAtRef.current = null;
    if (endAt !== null) {
      const left = Math.max(0, Math.ceil((endAt - Date.now()) / 1000));
      setRemaining(left);
    }
    setStatus('paused');
  }, [status, clearTimer]);

  const handleReset = useCallback(() => {
    clearTimer();
    endAtRef.current = null;
    setRemaining(totalSeconds);
    setStatus('idle');
  }, [clearTimer, totalSeconds]);

  const progress = totalSeconds > 0 ? (totalSeconds - remaining) / totalSeconds : 0;
  const percent = Math.min(100, Math.max(0, progress * 100));

  const statusText: Record<Status, string> = {
    idle: '准备开始',
    running: '计时中',
    paused: '已暂停',
    finished: '已完成',
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 16,
        padding: 24,
        borderRadius: 16,
        background: '#fff7f2',
        color: '#3a2c25',
        fontFamily: 'system-ui, -apple-system, sans-serif',
        maxWidth: 360,
        margin: '0 auto',
      }}
    >
      <h2 style={{ margin: 0, fontSize: 20 }}>{title}</h2>

      <div
        aria-live="polite"
        style={{
          fontSize: 64,
          fontWeight: 700,
          fontVariantNumeric: 'tabular-nums',
          letterSpacing: 2,
          color: status === 'finished' ? '#c0392b' : '#d35400',
        }}
      >
        {formatTime(remaining)}
      </div>

      <div style={{ width: '100%', height: 8, borderRadius: 4, background: '#f3d9cc', overflow: 'hidden' }}>
        <div
          style={{
            width: `${percent}%`,
            height: '100%',
            background: '#e67e22',
            transition: 'width 0.2s linear',
          }}
        />
      </div>

      <div style={{ fontSize: 14, color: '#8a6d5c' }}>{statusText[status]}</div>

      {status === 'finished' && (
        <div
          role="status"
          style={{
            padding: '8px 16px',
            borderRadius: 8,
            background: '#fdecea',
            color: '#c0392b',
            fontSize: 14,
            fontWeight: 600,
          }}
        >
          恭喜，番茄钟完成！休息一下吧。
        </div>
      )}

      <div style={{ display: 'flex', gap: 12 }}>
        {status === 'running' ? (
          <button type="button" onClick={handlePause} style={buttonStyle('#e67e22')}>
            暂停
          </button>
        ) : (
          <button
            type="button"
            onClick={handleStart}
            disabled={status === 'finished'}
            style={buttonStyle(status === 'finished' ? '#bdc3c7' : '#e67e22')}
          >
            开始
          </button>
        )}
        <button type="button" onClick={handleReset} style={buttonStyle('#95a5a6')}>
          重置
        </button>
      </div>
    </div>
  );
}

function buttonStyle(background: string): React.CSSProperties {
  return {
    padding: '10px 24px',
    borderRadius: 999,
    border: 'none',
    background,
    color: '#fff',
    fontSize: 15,
    fontWeight: 600,
    cursor: 'pointer',
  };
}
